/* El manual pide destacar siempre la última palabra del eslogan. */
export function Slogan({ size = 17, onDark = false }) {
  return (
    <p style={{ fontSize: size, fontWeight: 700, margin: 0, color: onDark ? "rgba(255,255,255,.75)" : "rgba(36,39,54,.7)" }}>
      Sentido para tu <span style={{ color: C.pink, fontWeight: 800 }}>Español</span>
    </p>
  );
}

export function BrandMark({ size = 46, onNavy = false }) {
  const img = (
    <img src={LOGO_DATA} alt="Rayuela" style={{ width: "100%", height: "100%", objectFit: "contain", display: "block" }} />
  );
  if (onNavy) return <div style={{ width: size, height: size, flex: "0 0 auto" }}>{img}</div>;
  const pad = Math.max(4, Math.round(size * 0.13));
  return (
    <div style={{ width: size, height: size, flex: "0 0 auto", background: C.navy, borderRadius: Math.round(size * 0.26), padding: pad, boxShadow: "0 6px 16px rgba(36,39,54,.18)" }}>
      <div style={{ width: "100%", height: "100%" }}>{img}</div>
    </div>
  );
}

function Dots({ color, style }) {
  const r = [];
  for (let y = 0; y < 6; y++) for (let x = 0; x < 6; x++) r.push(<circle key={x + "-" + y} cx={4 + x * 11} cy={4 + y * 11} r="2.1" fill={color} />);
  return (
    <svg width="70" height="70" viewBox="0 0 70 70" style={style} aria-hidden="true">{r}</svg>
  );
}

function Concentric({ color, style, size = 90 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 90 90" style={style} aria-hidden="true">
      {[40, 31, 22, 13].map((rr) => (
        <circle key={rr} cx="45" cy="45" r={rr} fill="none" stroke={color} strokeWidth="2" />
      ))}
    </svg>
  );
}

function Wave({ color, width = 140, style }) {
  return (
    <svg width={width} height="20" viewBox="0 0 140 20" style={style} aria-hidden="true">
      <path d="M0 10 Q 17.5 0 35 10 T 70 10 T 105 10 T 140 10" fill="none" stroke={color} strokeWidth="4" strokeLinecap="round" />
    </svg>
  );
}

/* ---------- Rayuela / camino del repaso ---------- */
function Hopscotch({ total, graduated }) {
  const cells = [];
  for (let i = 0; i < total; i++) {
    const done = i < graduated;
    const current = i === graduated && graduated < total;
    const bg = done ? [C.teal, C.orange, C.pink][i % 3] : "transparent";
    cells.push(
      <div
        key={i}
        className={"cv-stone" + (current ? " cv-current" : "")}
        style={{
          width: 34, height: 34, borderRadius: 11, display: "flex",
          alignItems: "center", justifyContent: "center", flex: "0 0 auto",
          fontFamily: "'Barriecito',cursive", fontSize: 17,
          color: done ? C.white : current ? C.pink : "rgba(36,39,54,.32)",
          background: bg,
          border: done ? "none" : current ? `2.5px solid ${C.pink}` : "2px dashed rgba(36,39,54,.22)",
        }}
      >
        {i + 1}
      </div>
    );
  }
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center", justifyContent: "center" }}>
      {cells}
      <div
        style={{
          width: 42, height: 34, borderRadius: "11px 11px 20px 20px", flex: "0 0 auto",
          display: "flex", alignItems: "center", justifyContent: "center",
          fontFamily: "'Barriecito',cursive", fontSize: 13,
          color: graduated >= total ? C.navy : "rgba(36,39,54,.4)",
          background: graduated >= total ? C.orange : "transparent",
          border: graduated >= total ? "none" : "2px dashed rgba(36,39,54,.22)",
        }}
      >
        Cielo
      </div>
    </div>
  );
}

/* ============================================================
   APP
   ============================================================ */
export function StudentApp({ uid, onLogout, preview = false, previewData = null, onExitPreview = null }) {
  const [loaded, setLoaded] = useState(preview);
  const [screen, setScreen] = useState("home"); // home | review | done

  // cuaderno de la alumna (sincronizado con Firestore)
  const [deck, setDeck] = useState(preview && previewData ? previewData.deck : SEED_DECK);
  const [cards, setCards] = useState(preview && previewData ? previewData.cards : []);

  // sesión
  const [session, setSession] = useState(null);
  const [revealed, setRevealed] = useState(false);
  const [userAnswer, setUserAnswer] = useState("");

  // modo de repaso: "flashcard" (estilo Anki, sin escribir) o "escritura" (escribe y compara)
  const [mode, setMode] = useState("escritura");

  // mazos (clases) seleccionados para repasar
  const [selMazos, setSelMazos] = useState(null); // null = todos

  // ritual de repaso (tiempo)
  const [duration, setDuration] = useState(12 * 60); // segundos | null = sin tiempo
  const [tick, setTick] = useState(0);
  const [timeUpShown, setTimeUpShown] = useState(false);
  const [timerOff, setTimerOff] = useState(false);

  // evita bucles de escritura: guarda el último JSON conocido en Firestore
  const lastRemote = useRef(null);
  // marca cuándo se mostró el cartón actual (para medir el tiempo real por cartón)
  const cardShownAt = useRef(Date.now());

  /* cargar (suscripción en tiempo real al propio cuaderno) */
  useEffect(() => {
    if (preview) {
      if (previewData) { setDeck(previewData.deck); setCards(previewData.cards); }
      setLoaded(true);
      return;
    }
    if (!uid) return;
    const unsub = subscribeNotebook(uid, (data) => {
      if (data) {
        lastRemote.current = JSON.stringify({ deck: data.deck, cards: data.cards });
        setDeck({ ...SEED_DECK, ...data.deck });
        setCards(data.cards);
      }
      setLoaded(true);
    });
    return unsub;
  }, [uid, preview]);

  /* guardar (con debounce, sin reescribir lo que acaba de llegar) */
  useEffect(() => {
    if (!loaded || preview || !uid) return;
    const snapshot = JSON.stringify({ deck, cards });
    if (snapshot === lastRemote.current) return;
    const t = setTimeout(() => {
      lastRemote.current = snapshot;
      saveNotebook(uid, { deck, cards });
    }, 600);
    return () => clearTimeout(t);
  }, [deck, cards, loaded, preview, uid]);

  const now = Date.now();
  const mazos = useMemo(() => listMazos(cards), [cards]);
  const activeMazos = selMazos && selMazos.length ? selMazos : mazos;
  const inScope = useMemo(() => cards.filter((c) => activeMazos.includes(mazoOf(c))), [cards, activeMazos.join("|")]);
  const dueCards = useMemo(() => inScope.filter((c) => isDue(c, now)), [inScope]);
  const cardById = (id) => cards.find((c) => c.id === id);
  const currentCard = session && session.queue.length ? cardById(session.queue[0]) : null;

  // vista previa: cuántas frases entran en el tiempo elegido (para mostrarlo)
  const sessionPreview = useMemo(
    () => planSession(dueCards, duration, deck.avgSec),
    [dueCards, duration, deck.avgSec]
  );

  /* ---------- sesión ---------- */
  function startSession(useAll) {
    const pool = useAll ? inScope : dueCards;
    if (!pool.length) return;
    const plan = planSession(pool, duration, deck.avgSec);
    if (!plan.queue.length) return;
    setSession({
      queue: plan.queue,
      reserve: plan.reserve,
      initial: plan.queue.length,
      graduated: [],
      passes: {},
      ratings: {},
      answerSecs: [],
      startedAt: Date.now(),
      endedAt: null,
    });
    cardShownAt.current = Date.now();
    setRevealed(false);
    setUserAnswer("");
    setTick(0);
    setTimeUpShown(false);
    setTimerOff(false);
    setScreen("review");
  }

  function closeSession() {
    setSession((s) => (s ? { ...s, endedAt: s.endedAt || Date.now() } : s));
    setTimeUpShown(false);
    setScreen("done");
  }

  function rate(rating) {
    if (!currentCard) return;
    const id = currentCard.id;

    // tiempo real que tardó en este cartón (acotado para ignorar pausas largas)
    const spent = Math.min(180, Math.max(2, (Date.now() - cardShownAt.current) / 1000));

    // la fecha de revisión SOLO cambia aquí, al responder de verdad
    const sched = nextSchedule(currentCard.schedule, rating);
    setCards((prev) => prev.map((c) => (c.id === id ? { ...c, schedule: sched } : c)));

    // media móvil del tiempo por cartón (se persiste en el cuaderno)
    setDeck((d) => {
      const base = typeof d.avgSec === "number" && d.avgSec > 0 ? d.avgSec : BASELINE_SEC;
      return { ...d, avgSec: Math.round(base * 0.85 + spent * 0.15) };
    });

    setSession((prev) => {
      const passes = { ...prev.passes, [id]: (prev.passes[id] || 0) + 1 };
      const ratings = { ...prev.ratings, [id]: rating };
      const answerSecs = [...(prev.answerSecs || []), spent];
      let queue = prev.queue.slice(1);
      let graduated = prev.graduated;
      // sale de la sesión cuando su próxima revisión pasa a ser de un día o más
      // (etapa "review"); si sigue en (re)aprendizaje, vuelve a la cola de hoy.
      const graduate = (sched.nextReview - Date.now()) >= DAY || passes[id] >= 8;
      if (graduate) {
        if (!graduated.includes(id)) graduated = [...graduated, id];
      } else {
        const pos = rating === "again" ? 2 : rating === "hard" ? 4 : 6;
        const at = Math.min(pos, queue.length);
        queue = [...queue.slice(0, at), id, ...queue.slice(at)];
      }
      return { ...prev, queue, graduated, passes, ratings, answerSecs };
    });

    cardShownAt.current = Date.now();
    setRevealed(false);
    setUserAnswer("");
  }

  useEffect(() => {
    if (screen === "review" && session && session.queue.length === 0) {
      setSession((s) => (s ? { ...s, endedAt: s.endedAt || Date.now() } : s));
      setScreen("done");
    }
  }, [session, screen]);

  // reloj suave del ritual de repaso
  const startedAt = session ? session.startedAt : null;
  useEffect(() => {
    if (screen !== "review" || !startedAt || !duration || timerOff) return;
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [screen, startedAt, duration, timerOff]);

  const remainingSec =
    session && duration && !timerOff && startedAt
      ? Math.max(0, duration - Math.floor((Date.now() - startedAt) / 1000))
      : null;

  useEffect(() => {
    if (screen === "review" && duration && !timerOff && session && remainingSec === 0 && !timeUpShown) {
      setTimeUpShown(true);
    }
  }, [remainingSec, screen, duration, timerOff, timeUpShown, session]);

  // adaptación en vivo: si el alumno va rápido y queda tiempo, suma cartones
  // de la reserva; si va lento, no suma (y llegará antes al aviso de tiempo).
  useEffect(() => {
    if (screen !== "review" || !session || !duration || timerOff) return;
    if (!session.reserve || !session.reserve.length) return;
    const pf = personalFactor(deck.avgSec);
    const uniqQueue = Array.from(new Set(session.queue));
    const estRemaining = uniqQueue.reduce((s, id) => {
      const c = cardById(id);
      return c ? s + estCardSec(c, pf) : s;
    }, 0);
    const elapsed = (Date.now() - session.startedAt) / 1000;
    const nextCard = cardById(session.reserve[0]);
    const estNext = nextCard ? estCardSec(nextCard, pf) : 0;
    if (elapsed + estRemaining + estNext <= duration) {
      setSession((s) => (s && s.reserve && s.reserve.length
        ? { ...s, queue: [...s.queue, s.reserve[0]], reserve: s.reserve.slice(1), initial: s.initial + 1 }
        : s));
    }
  }, [screen, session, duration, timerOff, tick, deck.avgSec]);

  /* ============================================================ */
  if (!loaded) {
    return (
      <div className="cv-root" style={{ minHeight: 480, display: "flex", alignItems: "center", justifyContent: "center", background: C.cream }}>
        <style>{CSS}</style>
        <div className="cv-float"><BrandMark size={64} /></div>
      </div>
    );
  }

  const accountLabel = preview ? "← Volver" : "Cerrar sesión";
  const onAccount = preview ? onExitPreview : onLogout;

  return (
    <div className="cv-root" style={{ background: C.cream, minHeight: 600 }}>
      <style>{CSS}</style>
      {screen === "home" && cards.length === 0 && <Welcome onAccount={onAccount} accountLabel={accountLabel} onDemo={() => setCards(buildSeedCards())} />}
      {screen === "home" && cards.length > 0 && <Home deck={deck} dueCount={dueCards.length} total={inScope.length} plannedCount={sessionPreview.queue.length} plannedSec={sessionPreview.estSec} mazos={mazos} selMazos={selMazos} setSelMazos={setSelMazos} counts={cards} duration={duration} setDuration={setDuration} mode={mode} setMode={setMode} onStart={startSession} onAccount={onAccount} accountLabel={accountLabel} />}
      {screen === "review" && currentCard && (
        <Review
          card={currentCard}
          deck={deck}
          total={session.initial}
          graduated={session.graduated.length}
          remainingSec={remainingSec}
          mode={mode}
          onToggleMode={() => setMode((m) => (m === "flashcard" ? "escritura" : "flashcard"))}
          revealed={revealed}
          userAnswer={userAnswer}
          onAnswer={setUserAnswer}
          onReveal={() => setRevealed(true)}
          onRate={rate}
          onExit={() => setScreen("home")}
        />
      )}
      {screen === "review" && timeUpShown && (
        <TimeUp onClose={closeSession} onContinue={() => { setTimerOff(true); setTimeUpShown(false); }} />
      )}
      {screen === "done" && <Done session={session} onHome={() => setScreen("home")} />}
    </div>
  );
}

/* ============================================================
   HOME — área de la alumna
   ============================================================ */
function Home({ deck, dueCount, total, plannedCount, plannedSec, mazos, selMazos, setSelMazos, counts, duration, setDuration, mode, setMode, onStart, onAccount, accountLabel }) {
  const [showHelp, setShowHelp] = useState(false);
  return (
    <div style={{ position: "relative", overflow: "hidden", minHeight: 600 }}>
      <Concentric color={C.teal} style={{ position: "absolute", bottom: -10, left: -18, opacity: 0.35 }} />

      <div className="cv-pad" style={{ maxWidth: 620, margin: "0 auto", padding: "22px 32px 48px", position: "relative" }}>
        <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 12 }}>
          <button className="cv-link" onClick={onAccount} style={{ fontSize: 15, fontWeight: 800, color: "rgba(36,39,54,.55)" }}>{accountLabel}</button>
        </div>

        <div style={{ textAlign: "center", marginTop: 2 }}>
          <div style={{ display: "flex", justifyContent: "center" }}>
            <BrandMark size={82} />
          </div>
          <div style={{ display: "flex", justifyContent: "center", marginTop: 8 }}>
            <Wave color={C.orange} width={130} />
          </div>
        </div>

        <div style={{ textAlign: "center", marginTop: 26 }}>
          <div className="cv-float" style={{ display: "inline-block", marginBottom: 6 }}>
            <Hopscotch total={Math.min(total, 7)} graduated={0} />
          </div>
          <h1 className="cv-display" style={{ fontSize: "clamp(46px,12vw,72px)", margin: "16px 0 2px", color: C.navy, lineHeight: 1 }}>
            Cuaderno Vivo
          </h1>
          <Slogan />
          <p style={{ fontSize: 15, color: "rgba(36,39,54,.72)", fontWeight: 600, maxWidth: 480, margin: "14px auto 0", lineHeight: 1.55 }}>
            Tu cuaderno reúne las frases y correcciones de tus clases y te las devuelve poco a poco para repasar. Así fijas lo que aprendiste y ganas soltura al hablar.
          </p>
          <button
            className="cv-link"
            onClick={() => setShowHelp(true)}
            style={{ marginTop: 12, fontSize: 14, fontWeight: 800, color: C.teal, textDecoration: "underline" }}
          >
            Cómo funciona y cómo utilizar tu Cuaderno
          </button>
        </div>

        <div className="cv-fade" style={{ background: C.creamSoft, borderRadius: 28, padding: 26, marginTop: 32, boxShadow: "0 14px 40px rgba(36,39,54,.08)", border: "1px solid rgba(36,39,54,.06)" }}>
          <p className="cv-display" style={{ margin: "0 0 2px", color: C.pink, fontSize: 34, lineHeight: 1.05 }}>
            {deck.studentName ? `Hola, ${deck.studentName} ✨` : "Hola ✨"}
          </p>
          <p style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.navy }}>{deck.name}</p>

          <div style={{ display: "flex", gap: 14, margin: "20px 0 24px", flexWrap: "wrap" }}>
            <Stat n={dueCount} label="frases te esperan hoy" color={C.pink} />
            <Stat n={total} label="frases en tu cuaderno" color={C.teal} />
          </div>

          <MazoChooser mazos={mazos} selMazos={selMazos} setSelMazos={setSelMazos} cards={counts} />

          <ModeChooser mode={mode} setMode={setMode} />

          <RitualChooser duration={duration} setDuration={setDuration} />

          {dueCount > 0 ? (
            <>
              <p style={{ textAlign: "center", fontSize: 14, fontWeight: 700, color: "rgba(36,39,54,.6)", margin: "0 0 12px" }}>
                {duration
                  ? `En ${Math.round(duration / 60)} min repasarás unas ${plannedCount} de las ${dueCount} frases pendientes.`
                  : `Repasarás las ${plannedCount} frases pendientes, sin límite de tiempo.`}
              </p>
              <button
                className="cv-btn"
                onClick={() => onStart(false)}
                style={{ width: "100%", padding: "18px", fontSize: 19, background: C.pink, color: C.white, boxShadow: "0 10px 24px rgba(237,76,135,.34)" }}
              >
                EMPEZAR MI REPASO →
              </button>
            </>
          ) : (
            <div style={{ textAlign: "center" }}>
              <p style={{ fontWeight: 800, color: C.teal, fontSize: 17, marginTop: 0 }}>Hoy no hay frases pendientes 🌿</p>
              <button className="cv-btn" onClick={() => onStart(true)} style={{ padding: "14px 24px", fontSize: 16, background: C.orange, color: C.navy }}>
                Repasar de todos modos
              </button>
            </div>
          )}
        </div>
      </div>
      {showHelp && <HowItWorksModal onClose={() => setShowHelp(false)} />}
    </div>
  );
}

