function MazoChooser({ mazos, selMazos, setSelMazos, cards }) {
  const [multi, setMulti] = useState(false);
  if (!mazos || mazos.length < 2) return null;
  const all = !selMazos || !selMazos.length;
  const isOn = (m) => (all ? false : selMazos.includes(m));

  function tap(m) {
    if (!multi) { setSelMazos([m]); return; }          // toque directo: solo esa clase
    const cur = all ? [] : selMazos;
    const next = cur.includes(m) ? cur.filter((x) => x !== m) : [...cur, m];
    setSelMazos(next.length ? next : null);
  }

  const count = (m) => cards.filter((c) => mazoOf(c) === m).length;
  return (
    <div style={{ marginBottom: 22 }}>
      <p className="cv-display" style={{ margin: "0 0 2px", fontSize: 22, color: C.navy }}>¿Qué clases quieres repasar?</p>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 10, margin: "0 0 12px", flexWrap: "wrap" }}>
        <span style={{ fontSize: 13.5, color: "rgba(36,39,54,.62)", fontWeight: 600 }}>
          {multi ? "Toca varias para combinarlas." : "Toca la clase que quieras repasar."}
        </span>
        <button className="cv-link" onClick={() => { setMulti(!multi); }} style={{ fontSize: 13, color: multi ? C.pink : "rgba(36,39,54,.5)" }}>
          {multi ? "✓ Combinando varias" : "Combinar varias"}
        </button>
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button
          className="cv-tap"
          onClick={() => setSelMazos(null)}
          style={{ padding: "9px 15px", borderRadius: 999, fontWeight: 800, fontSize: 13.5,
            border: `2px solid ${all ? C.pink : "rgba(36,39,54,.16)"}`,
            background: all ? C.pink : C.white, color: all ? C.white : C.navy }}
        >
          Todas
        </button>
        {mazos.map((m) => {
          const on = isOn(m);
          return (
            <button
              key={m}
              className="cv-tap"
              onClick={() => tap(m)}
              style={{ padding: "9px 15px", borderRadius: 999, fontWeight: 800, fontSize: 13.5,
                border: `2px solid ${on ? C.teal : "rgba(36,39,54,.16)"}`,
                background: on ? "rgba(108,167,183,.2)" : C.white, color: on ? C.teal : "rgba(36,39,54,.7)" }}
            >
              {on ? "✓ " : ""}{m} · {count(m)}
            </button>
          );
        })}
      </div>
    </div>
  );
}

