/** Lee y valida el contenido de un archivo .json de importación.
 *  Acepta tanto una lista simple de tarjetas [...] como un objeto
 *  { deckName, date, cards: [...] } (formato de un cuaderno exportado antes). */
function parseImportJson(raw) {
  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    return { error: "El archivo no contiene un JSON válido" };
  }

  let list, title = "", dateField = "";
  if (Array.isArray(data)) {
    list = data;
  } else if (data && typeof data === "object" && Array.isArray(data.cards)) {
    list = data.cards;
    title = String(data.deckName || data.title || "").trim();
    dateField = String(data.date || "").trim();
  } else {
    return { error: "La estructura del archivo no es la esperada" };
  }

  if (!list.length) return { error: "La estructura del archivo no es la esperada" };

  const norm = [];
  for (const item of list) {
    if (!item || typeof item !== "object") return { error: "La estructura del archivo no es la esperada" };
    if (!TYPES.includes(item.type)) return { error: "La estructura del archivo no es la esperada" };
    if (!item.front || !item.answer) return { error: "La estructura del archivo no es la esperada" };
    norm.push({
      id: item.id || uid(),
      type: item.type,
      front: String(item.front),
      answer: String(item.answer),
      note: item.note ? String(item.note) : "",
      example: item.example ? String(item.example) : "",
      tags: Array.isArray(item.tags) ? item.tags : [],
      ...(item.hints && typeof item.hints === "object" ? { hints: item.hints } : {}),
      schedule: freshSchedule(),
    });
  }
  return { cards: norm, title, dateField };
}

/* Fecha de hoy en ISO (yyyy-mm-dd) para el input date. */
function todayISO() {
  return new Date().toISOString().slice(0, 10);
}
/* Pasa una fecha ISO (yyyy-mm-dd) a formato corto dd/mm/aaaa para el nombre del bloque. */
function isoToEs(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ""));
  return m ? `${m[3]}/${m[2]}/${m[1]}` : String(iso || "");
}

function TeacherImport({ student, setCards }) {
  const [fileName, setFileName] = useState("");
  const [status, setStatus] = useState(null); // { ok, text }
  const [dragOver, setDragOver] = useState(false);
  const [pending, setPending] = useState(null); // frases validadas, aún sin agregar
  const [blockName, setBlockName] = useState("");
  const [date, setDate] = useState(todayISO());
  const inputRef = useRef(null);

  function handleFile(file) {
    if (!file || !/\.json$/i.test(file.name)) {
      setFileName(file ? file.name : "");
      setPending(null);
      setStatus({ ok: false, text: "Selecciona un archivo .json para continuar" });
      return;
    }
    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = () => {
      const r = parseImportJson(String(reader.result || ""));
      if (r.error) { setPending(null); setStatus({ ok: false, text: r.error }); return; }
      const d = /^\d{4}-\d{2}-\d{2}$/.test(r.dateField) ? r.dateField : todayISO();
      setDate(d);
      setBlockName(r.title || `Clase ${isoToEs(d)}`);
      setPending(r.cards);
      setStatus({ ok: true, text: `Archivo cargado correctamente · ${r.cards.length} frase${r.cards.length === 1 ? "" : "s"} detectada${r.cards.length === 1 ? "" : "s"}.` });
    };
    reader.onerror = () => { setPending(null); setStatus({ ok: false, text: "El archivo no contiene un JSON válido" }); };
    reader.readAsText(file);
  }

  function onInputChange(e) {
    handleFile(e.target.files && e.target.files[0]);
    e.target.value = "";
  }
  function onDrop(e) {
    e.preventDefault();
    setDragOver(false);
    handleFile(e.dataTransfer.files && e.dataTransfer.files[0]);
  }

  function add() {
    if (!pending || !pending.length) return;
    const name = blockName.trim() || `Clase ${isoToEs(date)}`;
    const withBlock = pending.map((c) => ({ ...c, mazo: name, classDate: date }));
    setCards((prev) => mergeCards(prev, withBlock).cards);
    const n = pending.length;
    setPending(null);
    setFileName("");
    setStatus({ ok: true, text: `Listo: ${n} frase${n === 1 ? "" : "s"} añadida${n === 1 ? "" : "s"} a «${name}» en la Biblioteca de ${student.name}.` });
  }

  return (
    <Panel>
      <H>Importar JSON</H>
      <p style={{ fontSize: 14, color: "rgba(255,255,255,.65)", marginTop: 0, marginBottom: 16 }}>
        Sube el archivo .json que generó Claude con las frases de la clase de {student.name}.
        Cada importación crea su propio bloque en la Biblioteca, con su nombre y su fecha.
      </p>

      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
        onClick={() => inputRef.current && inputRef.current.click()}
        style={{
          cursor: "pointer", borderRadius: 20, padding: "30px 20px", textAlign: "center",
          border: `2.5px dashed ${dragOver ? C.teal : "rgba(255,255,255,.25)"}`,
          background: dragOver ? "rgba(108,167,183,.16)" : "rgba(255,255,255,.04)",
          transition: "border-color .15s ease, background .15s ease",
        }}
      >
        <input ref={inputRef} type="file" accept=".json,application/json" onChange={onInputChange} style={{ display: "none" }} />
        <div style={{ fontSize: 30, marginBottom: 10, lineHeight: 1 }}>📄</div>
        <button
          type="button"
          className="cv-btn"
          onClick={(e) => { e.stopPropagation(); inputRef.current && inputRef.current.click(); }}
          style={{ padding: "12px 22px", fontSize: 14.5, background: C.pink, color: C.white }}
        >
          Seleccionar archivo .json
        </button>
        <p style={{ margin: "12px 0 0", fontSize: 13, fontWeight: 700, color: "rgba(255,255,255,.5)" }}>
          o arrastra y suelta el archivo aquí
        </p>
        {fileName && (
          <p style={{ margin: "12px 0 0", fontSize: 13.5, fontWeight: 800, color: C.orange }}>📎 {fileName}</p>
        )}
      </div>

      {status && (
        <div style={{ marginTop: 14, padding: "13px 16px", borderRadius: 14, fontWeight: 700, fontSize: 14, background: status.ok ? "rgba(108,167,183,.25)" : "rgba(237,76,135,.22)", color: C.white, border: `1px solid ${status.ok ? C.teal : C.pink}` }}>
          {status.ok ? "✓ " : "⚠ "}{status.text}
        </div>
      )}

      {pending && (
        <div className="cv-fade" style={{ marginTop: 18 }}>
          <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
            <div style={{ flex: "2 1 220px" }}>
              <label style={labelStyle}>Nombre de esta clase (así la alumna la elige después)</label>
              <input className="cv-input" value={blockName} onChange={(e) => setBlockName(e.target.value)} placeholder="Clase de conversación" />
            </div>
            <div style={{ flex: "1 1 140px" }}>
              <label style={labelStyle}>Fecha de la clase</label>
              <input className="cv-input" type="date" value={date} onChange={(e) => setDate(e.target.value)} />
            </div>
          </div>
          <button
            className="cv-btn"
            onClick={add}
            style={{ marginTop: 14, padding: "12px 22px", fontSize: 15, background: C.teal, color: C.white }}
          >
            Agregar a la Biblioteca
          </button>
        </div>
      )}
    </Panel>
  );
}

function TeacherLibrary({ cards, setCards }) {
  const [editing, setEditing] = useState(null);

  function update(id, patch) {
    setCards((prev) => prev.map((c) => (c.id === id ? { ...c, ...patch } : c)));
  }
  function del(id) { setCards((prev) => prev.filter((c) => c.id !== id)); }
  function dup(card) {
    const copy = { ...card, id: uid(), schedule: { interval: 0, nextReview: null, timesReviewed: 0, lastRating: null } };
    setCards((prev) => {
      const i = prev.findIndex((c) => c.id === card.id);
      return [...prev.slice(0, i + 1), copy, ...prev.slice(i + 1)];
    });
  }

  if (!cards.length) return <Panel><H>Biblioteca de tarjetas</H><p style={{ color: "rgba(255,255,255,.6)" }}>Aún no hay tarjetas. Importa un JSON para empezar.</p></Panel>;

  return (
    <Panel>
      <H>Biblioteca de tarjetas</H>
      {listMazos(cards).map((mz) => (
        <div key={mz} style={{ marginBottom: 22 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "0 0 10px", flexWrap: "wrap" }}>
            <span className="cv-display" style={{ fontSize: 20, color: C.orange }}>{mz}</span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: "rgba(255,255,255,.5)" }}>
              {cards.filter((c) => mazoOf(c) === mz).length} frases
            </span>
            <ConfirmBtn label="Eliminar clase" confirmLabel="¿Seguro? Toca otra vez" color={C.pink} onConfirm={() => setCards((prev) => prev.filter((c) => mazoOf(c) !== mz))} />
          </div>
      <div style={{ display: "grid", gap: 12 }}>
        {cards.filter((c) => mazoOf(c) === mz).map((card) => (
          <div key={card.id} style={{ background: "rgba(255,255,255,.06)", borderRadius: 16, padding: 16, border: "1px solid rgba(255,255,255,.08)" }}>
            {editing === card.id ? (
              <CardEditor card={card} onChange={(patch) => update(card.id, patch)} onClose={() => setEditing(null)} />
            ) : (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
                  <span className="cv-chip" style={{ background: TYPE_COLOR[card.type], color: card.type === "hueco" ? C.navy : C.white }}>{TYPE_LABEL[card.type]}</span>
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                    <MiniBtn onClick={() => setEditing(card.id)} color={C.teal}>Editar</MiniBtn>
                    <MiniBtn onClick={() => dup(card)} color={C.orange}>Duplicar</MiniBtn>
                    <MiniBtn onClick={() => del(card.id)} color={C.pink}>Eliminar</MiniBtn>
                  </div>
                </div>
                <p style={{ margin: "10px 0 4px", fontWeight: 800, color: C.white, fontSize: 15 }}>{card.front}</p>
                <p style={{ margin: 0, fontSize: 14, color: C.orange, fontWeight: 700 }}>{card.answer}</p>
              </>
            )}
          </div>
        ))}
      </div>
        </div>
      ))}
    </Panel>
  );
}

function CardEditor({ card, onChange, onClose }) {
  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div>
        <label style={labelStyle}>Tipo</label>
        <select className="cv-input" value={card.type} onChange={(e) => onChange({ type: e.target.value })}>
          {TYPES.map((t) => <option key={t} value={t}>{TYPE_LABEL[t]}</option>)}
        </select>
      </div>
      <EditField label="Frente / pregunta" value={card.front} onChange={(v) => onChange({ front: v })} area />
      <EditField label="Respuesta" value={card.answer} onChange={(v) => onChange({ answer: v })} area />
      <EditField label="Pista / nota" value={card.note || ""} onChange={(v) => onChange({ note: v })} area />
      <EditField label="Ejemplo" value={card.example || ""} onChange={(v) => onChange({ example: v })} area />
      <EditField label="Clase / mazo" value={card.mazo || ""} onChange={(v) => onChange({ mazo: v })} />
      <EditField label="Tags (separa con ,)" value={(card.tags || []).join(", ")} onChange={(v) => onChange({ tags: v.split(",").map((s) => s.trim()).filter(Boolean) })} />
      <button className="cv-btn" onClick={onClose} style={{ padding: "10px 18px", fontSize: 13.5, background: C.teal, color: C.white, justifySelf: "start" }}>Listo</button>
    </div>
  );
}

function EditField({ label, value, onChange, area }) {
  return (
    <div>
      <label style={labelStyle}>{label}</label>
      {area ? (
        <textarea className="cv-input" rows={2} value={value} onChange={(e) => onChange(e.target.value)} />
      ) : (
        <input className="cv-input" value={value} onChange={(e) => onChange(e.target.value)} />
      )}
    </div>
  );
}

function MiniBtn({ children, onClick, color }) {
  return (
    <button className="cv-tap" onClick={onClick} style={{ padding: "5px 12px", borderRadius: 999, fontWeight: 800, fontSize: 12.5, color, border: `2px solid ${color}`, background: "transparent" }}>
      {children}
    </button>
  );
}

/** Confirmación en dos toques — no usa confirm() del navegador, que muchos contextos bloquean. */
function ConfirmBtn({ label, confirmLabel, onConfirm, color }) {
  const [armed, setArmed] = useState(false);
  useEffect(() => {
    if (!armed) return;
    const t = setTimeout(() => setArmed(false), 4000);
    return () => clearTimeout(t);
  }, [armed]);
  return (
    <button
      className="cv-tap"
      onClick={() => { if (armed) { setArmed(false); onConfirm(); } else setArmed(true); }}
      style={{
        padding: "5px 12px", borderRadius: 999, fontWeight: 800, fontSize: 12.5,
        color: armed ? C.white : color,
        border: `2px solid ${color}`,
        background: armed ? color : "transparent",
      }}
    >
      {armed ? (confirmLabel || "¿Seguro? Toca otra vez") : label}
    </button>
  );
}

function TeacherPrompt() {
  const [copied, setCopied] = useState(false);
  const ref = useRef(null);
  async function copy() {
    try {
      await navigator.clipboard.writeText(TEACHER_PROMPT);
      setCopied(true); setTimeout(() => setCopied(false), 1800);
    } catch (e) {
      if (ref.current) { ref.current.select(); document.execCommand("copy"); setCopied(true); setTimeout(() => setCopied(false), 1800); }
    }
  }
  return (
    <Panel>
      <H>Prompt para transformar el chat de la clase</H>
      <p style={{ fontSize: 14, color: "rgba(255,255,255,.65)", marginTop: 0 }}>
        Copia este prompt y pégalo en Claude junto con el chat de la aula. Te devolverá el JSON listo para importar.
      </p>
      <textarea ref={ref} className="cv-input" rows={12} readOnly value={TEACHER_PROMPT} style={{ fontFamily: "monospace", fontSize: 12.5, lineHeight: 1.6 }} />
      <button className="cv-btn" onClick={copy} style={{ marginTop: 14, padding: "12px 22px", fontSize: 15, background: copied ? C.teal : C.pink, color: C.white }}>
        {copied ? "✓ Copiado" : "Copiar prompt"}
      </button>
    </Panel>
  );
}

/* ---------- piezas del modo profesora ---------- */
function Panel({ children }) {
  return <div className="cv-fade" style={{ background: "rgba(255,255,255,.04)", borderRadius: 22, padding: 24, border: "1px solid rgba(255,255,255,.08)" }}>{children}</div>;
}
function H({ children }) {
  return <h2 className="cv-display" style={{ fontSize: 26, color: C.white, margin: "0 0 16px" }}>{children}</h2>;
}

/* ============================================================
   MODO PROFESORA (contenedor con datos de Firestore)
   ============================================================ */
const TEACHER_CODE = "unicornica1411";

function docJson(s) {
  return JSON.stringify({ name: s.name, level: s.level, deckName: s.deckName, date: s.date, cards: s.cards });
}

export function TeacherApp({ uid, onLogout }) {
  const [roster, setRoster] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [preview, setPreview] = useState(null);
  const lastSaved = useRef({}); // uid -> json ya guardado en Firestore

  // suscripción en tiempo real a las alumnas de esta profesora
  useEffect(() => {
    if (!uid) return;
    const unsub = subscribeRoster(uid, (list) => {
      setRoster((prev) => {
        const prevById = new Map(prev.map((s) => [s.id, s]));
        return list.map((remote) => {
          const local = prevById.get(remote.id);
          // conserva ediciones locales aún sin guardar
          if (local && lastSaved.current[remote.id] !== docJson(local)) return local;
          lastSaved.current[remote.id] = docJson(remote);
          return remote;
        });
      });
      for (const r of list) {
        if (lastSaved.current[r.id] === undefined) lastSaved.current[r.id] = docJson(r);
      }
      setLoaded(true);
    });
    return unsub;
  }, [uid]);

  // guarda (con debounce) los documentos que cambiaron localmente
  useEffect(() => {
    if (!loaded) return;
    const t = setTimeout(() => {
      for (const s of roster) {
        const key = docJson(s);
        if (lastSaved.current[s.id] !== key) {
          lastSaved.current[s.id] = key;
          saveStudentDoc(s.id, { name: s.name, level: s.level, deckName: s.deckName, date: s.date, cards: s.cards });
        }
      }
    }, 700);
    return () => clearTimeout(t);
  }, [roster, loaded]);

  async function onAddStudent({ name, user, password }) {
    return await createStudent(uid, { name, user, password });
  }

  function onRemoveStudent(id) {
    delete lastSaved.current[id];
    setRoster((prev) => prev.filter((s) => s.id !== id));
    removeStudentDoc(id);
  }

  if (preview) {
    const previewData = {
      deck: { studentName: preview.name, level: preview.level, name: preview.deckName, date: preview.date },
      cards: (preview.cards || []).map((c) => ({ ...c, schedule: c.schedule || freshSchedule() })),
    };
    return <StudentApp preview previewData={previewData} onExitPreview={() => setPreview(null)} />;
  }

  return (
    <Teacher
      roster={roster}
      setRoster={setRoster}
      onAddStudent={onAddStudent}
      onRemoveStudent={onRemoveStudent}
      onPreview={setPreview}
      onLogout={onLogout}
    />
  );
}

/* ============================================================
   LOGIN — usuario + contraseña (Firebase Auth)
   ============================================================ */
export function Login() {
  const [mode, setMode] = useState("login"); // login | teacher
  const [name, setName] = useState("");
  const [user, setUser] = useState("");
  const [password, setPassword] = useState("");
  const [code, setCode] = useState("");
  const [err, setErr] = useState(null);
  const [busy, setBusy] = useState(false);

  async function doLogin() {
    if (!user.trim() || !password) { setErr("Escribe tu usuario y tu contraseña."); return; }
    setBusy(true); setErr(null);
    try {
      await signInWithEmailAndPassword(auth, toEmail(user), password);
    } catch (e) {
      setErr("Usuario o contraseña incorrectos.");
    }
    setBusy(false);
  }

  async function doTeacher() {
    if (code !== TEACHER_CODE) { setErr("Código de profesora incorrecto."); return; }
    if (!user.trim() || password.length < 6) { setErr("Usa un usuario y una contraseña de al menos 6 caracteres."); return; }
    setBusy(true); setErr(null);
    try {
      const email = toEmail(user);
      const cred = await createUserWithEmailAndPassword(auth, email, password);
      await createTeacherProfile(cred.user.uid, { name: name.trim() || "Profesora", email });
    } catch (e) {
      const c = e && e.code;
      setErr(c === "auth/email-already-in-use" ? "Ese usuario ya existe. Inicia sesión." : "No se pudo crear la cuenta de profesora.");
    }
    setBusy(false);
  }

  const teacher = mode === "teacher";
  const submit = teacher ? doTeacher : doLogin;

  return (
    <div className="cv-root" style={{ background: C.cream, minHeight: 600 }}>
      <style>{CSS}</style>
      <div className="cv-pad" style={{ maxWidth: 440, margin: "0 auto", padding: "48px 32px", textAlign: "center", position: "relative" }}>
        <div style={{ display: "inline-block", marginBottom: 14 }}><BrandMark size={64} /></div>
        <h1 className="cv-display" style={{ fontSize: 44, color: C.navy, margin: "0 0 2px", lineHeight: 1 }}>Cuaderno Vivo</h1>
        <Slogan />

        <div style={{ background: C.creamSoft, borderRadius: 24, padding: 24, marginTop: 26, boxShadow: "0 14px 40px rgba(36,39,54,.08)", border: "1px solid rgba(36,39,54,.06)", textAlign: "left" }}>
          <p className="cv-display" style={{ margin: "0 0 16px", fontSize: 26, color: C.pink, textAlign: "center" }}>
            {teacher ? "Crear cuenta de profesora" : "Entrar a tu cuaderno"}
          </p>

          {teacher && (
            <input className="cv-input" style={{ marginBottom: 10 }} value={name} placeholder="Tu nombre" onChange={(e) => { setName(e.target.value); setErr(null); }} />
          )}
          <input
            className="cv-input"
            style={{ marginBottom: 10 }}
            value={user}
            placeholder="Usuario"
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck="false"
            onChange={(e) => { setUser(e.target.value); setErr(null); }}
            onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
          />
          <input
            className="cv-input"
            style={{ marginBottom: 10 }}
            type="password"
            value={password}
            placeholder="Contraseña"
            onChange={(e) => { setPassword(e.target.value); setErr(null); }}
            onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
          />
          {teacher && (
            <input
              className="cv-input"
              style={{ marginBottom: 10 }}
              type="password"
              value={code}
              placeholder="Código de profesora"
              onChange={(e) => { setCode(e.target.value); setErr(null); }}
              onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
            />
          )}

          {err && <p style={{ color: C.pink, fontWeight: 700, fontSize: 14, margin: "0 0 10px" }}>{err}</p>}

          <button className="cv-btn" onClick={submit} disabled={busy} style={{ width: "100%", padding: 15, fontSize: 16, background: busy ? "rgba(36,39,54,.2)" : C.pink, color: C.white }}>
            {busy ? "Un momento..." : teacher ? "Crear cuenta" : "Entrar"}
          </button>
        </div>

        <button
          className="cv-link"
          onClick={() => { setMode(teacher ? "login" : "teacher"); setErr(null); }}
          style={{ marginTop: 20, color: "rgba(36,39,54,.55)" }}
        >
          {teacher ? "← Ya tengo cuenta, entrar" : "Soy profesora · crear cuenta"}
        </button>
      </div>
    </div>
  );
}
